class GitWrapper:

    def __init__(self):
        self.git = __import__('git')

    def checkout(self, branch_name):
        try: 
            repo = self.git.Repo('.')
            repo.heads[branch_name].checkout()
        except Exception as e:
            print(e)

    def add_file(self, file_path):
        try: 
            repo = self.git.Repo('.')   
            repo.index.add(file_path)
        except Exception as e:
            print(e)
